import {
	Component,
	Element,
	Event,
	type EventEmitter,
	Host,
	Prop,
	State,
	Watch,
	h,
} from "@stencil/core";
import { alertsNegativeLarge, paperclip, trashSimple } from "../../../icons";
import getBootstrapConfig from "../../utils/getBootstrapConfig";
import { hasSlot } from "../../utils/slot";

let id = 0;

/**
 * @since 1.1.5
 * @status stable
 *
 * @slot - The file item's label.
 * @slot prefix - Used to prepend an icon or similar element to the file item.
 * @slot suffix - Used to append an icon or similar element to the file item.
 * @slot error - Used to append an error message to the file item.
 * @slot thumbnail - custom thumbnail element
 *
 * @part base - The component's base wrapper.
 * @part file-item - The container that wraps the entire file item.
 * @part file-name - The container that wraps the file name and prefix.
 * @part prefix - The container that wraps the prefix.
 * @part prefix-icon - The paper clip or error icon element.
 * @part suffix - The container that wraps the suffix.
 * @part label - The container that wraps the file name.
 * @part error - The container that wraps the error message.
 * @part thumbnail - The container that wraps the thumbnail image.
 *
 * @data-testid removeFile - The file remove button wrapper.
 * @data-testid fileName - The element displaying the file name.
 */

@Component({
	tag: "hbr-file-item",
	styleUrl: "file-item.scss",
	shadow: true,
})
export class FileItem {
	/** Ref items */
	fileItem: HTMLElement;
	fileLabel: HTMLElement;
	container: HTMLElement;
	imageRef: HTMLElement | SVGElement;

	scrollWidth: number;
	private _scrollWidth: number;
	componentId = `hbr-file-item-${++id}`;

	// private mutationObserver: MutationObserver;
	resizeObserver: ResizeObserver;

	@Element() host: HTMLHbrFileItemElement;

	@State() hasPrefix = false;
	@State() hasSuffix = false;
	@State() hasError = false;
	@State() hasThumbnailSlot = false;
	@State() longName: string;

	/** File object which usually comes from the uploader */
	@Prop() file;

	/** Set to true to disable the file item. */
	@Prop({ reflect: true }) disabled: boolean;

	/** The file-item’s size. */
	@Prop({ reflect: true }) size: "small" | "medium" = "medium";

	/** Thumbnail preview */
	@Prop() thumbnail: boolean;

	/** Indicates file uploading state */
	@Prop({ reflect: true }) state: string;

	/** Indicates file uploading progress percentage  */
	@Prop() percentage: number;

	/** custom style. default is Magnetic design system */
	@Prop() custom: boolean;

	/** Attributes related to screen readers. */
	@Prop() aria: { removeFileLabel: string; progressLabel: string };

	/** Prevents removal while preserving file name details. */
	@Prop({ reflect: true }) readonly = false;

	/** Emitted when an uploaded file has removed */
	@Event({ eventName: "hbr-remove" }) hbrRemove: EventEmitter;

	@Watch("disabled")
	handleDisabledState() {
		this.host.setAttribute("aria-disabled", this.disabled ? "true" : "false");
	}

	private handleFileDeleteClick() {
		this.hbrRemove.emit(this.file);
	}

	private handleSlotChange() {
		this.hasPrefix = hasSlot(this.host, "prefix");
		this.hasSuffix = hasSlot(this.host, "suffix");
		this.hasError = hasSlot(this.host, "error");
		this.hasThumbnailSlot = hasSlot(this.host, "thumbnail");
	}

	renderPrefix = (thumbnail: boolean, state: string) => {
		const customSystemIcons = getBootstrapConfig()?.systemIcons;

		if (!this.hasPrefix) {
			if (state === "error") {
				return (
					<hbr-icon
						part="prefix-icon"
						asset={
							customSystemIcons?.["alerts-negative-large"] ||
							alertsNegativeLarge
						}
						class="file-item__icon--error"
					/>
				);
			}
			if (!thumbnail) {
				return (
					<hbr-icon
						asset={customSystemIcons?.paperclip || paperclip}
						part="prefix-icon"
						class="file-item__paperclip"
					/>
				);
			}
		}

		if (this.hasPrefix) {
			// Make sure to render if this.hasPrefix to prevent adding few extra pixels on DOM even with dimension of 0*0 when prefix was not set
			return (
				<span part="prefix" class="file-item__prefix">
					<slot name="prefix" />
				</span>
			);
		}
	};
	renderSuffix = (state: string, percentage: number) => {
		if (!this.hasSuffix) {
			return state ? this.stateIconSuffix(state, percentage) : "";
		}
		return (
			<span part="suffix" class="file-item__suffix">
				<slot name="suffix" />
			</span>
		);
	};

	stateIconSuffix = (state: string, percentage: number) => {
		const customSystemIcons = getBootstrapConfig()?.systemIcons;
		switch (state) {
			case "loading":
				return (
					<hbr-spinner
						part="suffix"
						class="file-item__suffix file-item__status-icon loading"
					/>
				);
			case "progress":
				return (
					<hbr-progress-bar
						style={{ minWidth: "var(--progress-min-width)" }}
						percentage={percentage}
						size={this.size}
						no-suffix={true}
						aria={{ label: this.aria?.progressLabel || "File upload progress" }}
					/>
				);
			default:
				if (this.readonly) {
					return "";
				}
				return (
					<hbr-button
						variant="text"
						part="suffix"
						exportparts="base:trash-button"
						arialabel={this.aria?.removeFileLabel || "Delete this file"}
						data-testid="removeFile"
						onClick={this.handleFileDeleteClick.bind(this)}
						class="file-item__suffix file-item__status-icon remove"
					>
						<hbr-icon
							asset={customSystemIcons?.["trash-simple"] || trashSimple}
						/>
					</hbr-button>
				);
		}
	};

	private getThumbnails() {
		const { file } = this;
		const fileReader = new FileReader();
		const img = this.imageRef as HTMLImageElement; // Change the type to HTMLImageElement
		const imageFile = img.tagName === "IMG";
		if (imageFile) {
			fileReader.readAsDataURL(file);
			fileReader.onload = (event) => {
				img.src = event.target.result as string; // Cast event.target.result to string
			};
		}
	}

	private longFileName(fileLabel, file) {
		const scrollWidth = fileLabel.scrollWidth;
		// this.scrollWidth = scrollWidth;
		// Above throws
		// Uncaught TypeError: Cannot set property offsetWidth of #<HTMLElement> which has only a getter
		this._scrollWidth = scrollWidth;
		const clientWidth = this.fileLabel.clientWidth;
		const overflow = scrollWidth > clientWidth;
		if (overflow) {
			const oneLetterWidth = scrollWidth / file.name.length;
			/** try to figure out half point of the container */
			const halfWayToFitContainer = Math.round(
				clientWidth / 2 / oneLetterWidth,
			);

			/** internal state change to trigger re-render  */
			const { name } = file;
			this.longName = `${name.slice(
				0,
				halfWayToFitContainer - 2,
			)}...${name.slice(file.name.length + 2 - halfWayToFitContainer)}`;
		}
	}

	connectedCallback() {
		this.handleSlotChange = this.handleSlotChange.bind(this);
	}

	componentWillLoad() {
		this.handleSlotChange();
	}

	componentDidLoad() {
		const { custom, fileLabel, file } = this;
		if (!custom) {
			/** show ellipsis & tooltip if file name is long */
			this.longFileName(fileLabel, file);
		}
	}

	componentDidRender() {
		if (this.thumbnail && this.imageRef) {
			this.getThumbnails();
		}
	}

	render() {
		const { custom, state, file, thumbnail, percentage } = this;
		let single: boolean;
		let firstOfType: boolean;
		if (this.host.hasAttribute("data-idx")) {
			if (this.host.getAttribute("data-idx") === "0") {
				single = true;
			} else if (this.host.getAttribute("data-idx") === "1") {
				firstOfType = true;
			}
		}
		/** make <ul><li> for multiple but single will use just <div> since it's not a list */
		const LI = single ? "div" : "li";
		const imageFile = this.file.type.startsWith("image/");
		const disabledState =
			this.disabled ||
			this.file.state === "loading" ||
			this.file.state === "progress";

		return (
			<Host role={!single ? "listitem" : ""}>
				<LI
					ref={(el: HTMLElement) => {
						this.fileItem = el;
					}}
					part="base"
					role="presentation"
					class={{
						"file-item": true,
						"file-item--single": LI === "div",
						"file-item--disabled": this.disabled,
						"file-item--small": this.size === "small",
						"file-item--medium": this.size === "medium",
						"file-item--has-prefix": this.hasPrefix,
						"file-item--has-suffix": this.hasSuffix,
						"file-item--has-error": this.hasError,
						"file-item-first-of-type": firstOfType,
						"file-item--thumbnail": thumbnail,
						"file-item--readonly": this.readonly,
						...(this.state ? { [`file-item--${this.state}`]: true } : null),
					}}
				>
					<div part="file-item" class="file-item__container">
						{this.thumbnail ? (
							this.hasThumbnailSlot ? (
								<slot name="thumbnail" />
							) : file.state === "error" ? (
								<span part="thumbnail" class="file-item__thumbnail error" />
							) : imageFile ? (
								<img
									ref={(el) => {
										this.imageRef = el;
									}}
									alt=""
									aria-hidden="true"
									part="thumbnail"
									class="file-item__thumbnail"
								/>
							) : (
								<span
									part="thumbnail"
									class={`file-item__thumbnail no-image-available${
										disabledState ? " disabled" : ""
									}`}
								/>
							)
						) : (
							""
						)}
						<div
							part="file-name"
							class="file-item__name"
							ref={(el) => {
								this.container = el;
							}}
						>
							{this.renderPrefix(thumbnail, state)}
							{custom ? (
								<span part="label" class="file-item__label">
									<slot onSlotchange={this.handleSlotChange} />
								</span>
							) : (
								<span
									part="label"
									class="file-item__label"
									ref={(el) => {
										this.fileLabel = el;
									}}
									data-testid="fileName"
								>
									{this.longName ? (
										<hbr-tooltip
											content={this.file.name}
											style={{ "--max-width": `${this._scrollWidth}px` }}
											hoist={true}
										>
											{this.longName}
										</hbr-tooltip>
									) : (
										<slot onSlotchange={this.handleSlotChange}>
											{file.name}
										</slot>
									)}
								</span>
							)}
						</div>
						{this.renderSuffix(state, percentage)}
					</div>
					{this.hasError ? (
						<p part="error" class="file-item__error">
							<slot name="error" onSlotchange={this.handleSlotChange} />
						</p>
					) : (
						""
					)}
				</LI>
			</Host>
		);
	}
}
